// Process audio upload and prepare for processing
const data = $input.first().json;
const binaryData = $input.first().binary;

// Validate audio file
if (!binaryData || !binaryData.audio) {
  throw new Error('No audio file provided');
}

const audioFile = binaryData.audio;
const { sessionId, userId, characterId, language = 'en' } = data;

// Validate required fields
if (!sessionId || !userId || !characterId) {
  throw new Error('Missing required fields: sessionId, userId, characterId');
}

// Process audio metadata
const audioMetadata = {
  sessionId,
  userId,
  characterId,
  language,
  filename: audioFile.filename,
  mimeType: audioFile.mimeType,
  size: audioFile.size,
  timestamp: new Date().toISOString()
};

// Supported audio formats
const supportedFormats = ['audio/webm', 'audio/ogg', 'audio/wav', 'audio/mp3', 'audio/m4a'];
if (!supportedFormats.includes(audioFile.mimeType)) {
  throw new Error(`Unsupported audio format: ${audioFile.mimeType}`);
}

// Size validation (max 25MB)
if (audioFile.size > 25 * 1024 * 1024) {
  throw new Error('Audio file too large (max 25MB)');
}

return { 
  json: audioMetadata,
  binary: {
    audio: audioFile
  }
};

// Compress large audio files using FFmpeg
const audioData = $input.first().json;
const audioBinary = $input.first().binary.audio;

// Calculate compression ratio needed
const targetSize = 5 * 1024 * 1024; // 5MB
const compressionRatio = Math.min(1, targetSize / audioData.size);

// FFmpeg compression settings
const ffmpegCommand = [
  'ffmpeg',
  '-i', 'pipe:0',
  '-ar', '16000', // Sample rate: 16kHz
  '-ac', '1', // Mono
  '-b:a', '64k', // Bitrate: 64kbps
  '-f', 'webm',
  '-c:a', 'libopus',
  'pipe:1'
].join(' ');

return {
  json: {
    ...audioData,
    compressionRatio,
    ffmpegCommand,
    needsCompression: true
  },
  binary: {
    audio: audioBinary
  }
};

// Detect voice activity and prepare for transcription
const audioData = $input.first().json;

// Voice activity detection parameters
const vadConfig = {
  aggressiveness: 3,
  frameDuration: 30,
  paddingDuration: 300,
  triggerLevel: 0.5,
  triggerLevelMedian: 0.5,
  triggerLevelMean: 0.5,
  pre VadThresholdMedian: 0.5,
  pre VadThresholdMean: 0.5,
  postVadThresholdMedian: 0.5,
  postVadThresholdMean: 0.5
};

// Character voice profile for speaker identification
const characterVoiceProfile = {
  characterId: audioData.characterId,
  sessionId: audioData.sessionId,
  voiceFeatures: {
    pitch: null, // To be extracted
    formants: null, // To be extracted
    mfcc: null, // To be extracted
    spectralCentroid: null // To be extracted
  }
};

return {
  json: {
    ...audioData,
    vadConfig,
    characterVoiceProfile,
    processingStage: 'vad-detection'
  }
};

// Prepare transcription request with character context
const audioData = $input.first().json;
const vadResult = $input.first().json;

// Get character context for better transcription
const characterContext = {
  characterId: audioData.characterId,
  sessionId: audioData.sessionId,
  language: audioData.language,
  gameContext: {
    characterName: '', // Will be fetched from DB
    characterRace: '',
    characterClass: '',
    currentScene: '',
    knownVocabulary: [] // Character-specific terms
  }
};

// Transcription configuration
const transcriptionConfig = {
  model: 'whisper-1',
  language: audioData.language,
  temperature: 0.0,
  response_format: 'verbose_json',
  timestamp_granularities: ['word', 'segment'],
  prompt: generateTranscriptionPrompt(characterContext)
};

function generateTranscriptionPrompt(context) {
  return `D&D game session. Character: ${context.characterName}, Race: ${context.characterRace}, Class: ${context.characterClass}. Current scene: ${context.currentScene}. Listen for fantasy terms, character names, and game mechanics.`;
}

return {
  json: {
    ...audioData,
    transcriptionConfig,
    characterContext,
    speechSegments: vadResult.speechSegments || []
  }
};

// Process transcription results and apply character voice effects
const transcriptionResult = $input.first().json;
const audioData = $input.first().json;

// Extract transcription data
const transcription = {
  text: transcriptionResult.text,
  words: transcriptionResult.words || [],
  segments: transcriptionResult.segments || [],
  duration: transcriptionResult.duration,
  language: transcriptionResult.language
};

// Speaker identification and confidence
const speakerAnalysis = {
  identifiedCharacter: audioData.characterId,
  confidence: 0.95,
  voiceFeatures: extractVoiceFeatures(transcription.words)
};

function extractVoiceFeatures(words) {
  // Extract voice characteristics from word timings
  const features = {
    averageWordDuration: 0,
    speechRate: 0,
    pausePattern: [],
    pitchVariation: null // Would need additional audio analysis
  };

  if (words && words.length > 1) {
    const totalDuration = words[words.length - 1].end - words[0].start;
    features.averageWordDuration = totalDuration / words.length;
    features.speechRate = words.length / totalDuration * 60; // words per minute

    // Extract pause patterns
    for (let i = 1; i < words.length; i++) {
      const pause = words[i].start - words[i - 1].end;
      if (pause > 0.1) { // Significant pause
        features.pausePattern.push(pause);
      }
    }
  }

  return features;
}

// Character voice modulation settings
const voiceModulation = {
  characterId: audioData.characterId,
  voiceProfile: {
    pitch: 1.0,
    rate: 1.0,
    volume: 1.0,
    echo: 0.0,
    reverb: 0.0,
    distortion: 0.0
  },
  effects: []
};

return {
  json: {
    sessionId: audioData.sessionId,
    userId: audioData.userId,
    characterId: audioData.characterId,
    timestamp: new Date().toISOString(),
    transcription,
    speakerAnalysis,
    voiceModulation,
    audioMetadata: {
      originalSize: audioData.size,
      duration: transcription.duration,
      language: transcription.language
    }
  }
};
